-- ── SQL-only CHECKs (Prisma cannot express them) ─────────────────────
-- Shape backstops for src/production. stepFrom >= 0, not >= 1: "étape 0"
-- templates may come later (D10); the service refuses step 0 today.
ALTER TABLE "ProductionEvent"
  ADD CONSTRAINT "ProductionEvent_steps_check"
  CHECK ("stepFrom" >= 0 AND "stepTo" >= "stepFrom" AND "quantity" BETWEEN 1 AND 500);
-- A recipient exactly when the act is a delivery, and a recipient name
-- only on a delivery.
ALTER TABLE "ProductionEvent"
  ADD CONSTRAINT "ProductionEvent_recipient_check"
  CHECK (
    (("type" = 'aligner_delivered') = ("deliveredTo" IS NOT NULL))
    AND ("deliveredToName" IS NULL OR "type" = 'aligner_delivered')
  );
-- A cancel always carries its reason, and a reason only comes with a cancel.
ALTER TABLE "ProductionEvent"
  ADD CONSTRAINT "ProductionEvent_cancel_check"
  CHECK (("cancelledAt" IS NULL) = ("cancelReason" IS NULL));
-- Prisma creates scalar lists as nullable columns; every reader expects an
-- array (the default covers an omitted value, this refuses an explicit NULL).
ALTER TABLE "ProductionEvent"
  ADD CONSTRAINT "ProductionEvent_warnings_check"
  CHECK ("warnings" IS NOT NULL);

ALTER TABLE "ProductionNotice"
  ADD CONSTRAINT "ProductionNotice_attempts_check"
  CHECK ("attempts" >= 0);
-- A notice always reports on at least one event. Prisma lets a writer omit
-- the list (stored NULL), and cardinality(NULL) is NULL, which a CHECK lets
-- through: hence the explicit IS NOT NULL.
ALTER TABLE "ProductionNotice"
  ADD CONSTRAINT "ProductionNotice_eventIds_check"
  CHECK ("eventIds" IS NOT NULL AND cardinality("eventIds") >= 1);

-- Counters are distinct-step counts: never negative.
ALTER TABLE "ProductionProgress"
  ADD CONSTRAINT "ProductionProgress_counters_check"
  CHECK (
    "printedUpper" >= 0 AND "printedLower" >= 0 AND
    "thermoformedUpper" >= 0 AND "thermoformedLower" >= 0 AND
    "cutUpper" >= 0 AND "cutLower" >= 0 AND
    "deliveredUpper" >= 0 AND "deliveredLower" >= 0
  );
